1	export type Item = { type: string };
2	export type Step = { op: string; items?: Item[] };
3	export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
4	
5	export type StepResult = { premium: number };
6	export type ScenarioResult = { results: StepResult[] };
7	
8	const BASE_PREMIUMS: Record<string, number> = {
9	  sword: 100,
10	  amulet: 60,
11	  staff: 80,
12	  potion: 40,
13	  rune: 25,
14	  moonstone: 25,
15	};
16	
17	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
18	const PROCESSING_FEE = 5;
19	
20	const policyBasePremium = (items: Item[] = []): number =>
21	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
22	
23	const quotePremium = (items?: Item[]): number => {
24	  const policyBase = policyBasePremium(items);
25	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
26	  return Math.ceil(policyBase + firstInsuranceSurcharge + PROCESSING_FEE);
27	};
28	
29	export const runScenario = (scenario: Scenario): ScenarioResult => ({
30	  results: scenario.steps.map((step) => ({
31	    premium: quotePremium(step.items),
32	  })),
33	});
